begin;
create temp table t(k text, v text); grant all on t to authenticated, anon;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"8838982b-cc58-4f06-bc61-6f54aa521b51","role":"authenticated"}',true);
insert into t select 'A inc1', water_oz::text from public.increment_counter('2026-10-15','water_oz',16,'11111111-1111-1111-1111-111111111111');
insert into t select 'A replay same op', water_oz::text from public.increment_counter('2026-10-15','water_oz',16,'11111111-1111-1111-1111-111111111111');
insert into t select 'A clamp -500', water_oz::text from public.increment_counter('2026-10-15','water_oz',-500,'22222222-2222-2222-2222-222222222222');
insert into t select 'A patch walk', checks::text from public.patch_day('2026-10-15','{"checks":{"walk":true}}');
insert into t select 'A patch read (merge)', checks::text from public.patch_day('2026-10-15','{"checks":{"read":true}}');
insert into t select 'A steps 5500', steps::text from public.patch_day('2026-10-15','{"steps":5500}');
insert into t select 'A steps kept after check patch', steps::text from public.patch_day('2026-10-15','{"checks":{"clip":false}}');
insert into t select 'A exercise key 8', exercises::text from public.patch_day('2026-10-15','{"exercises":{"8":true}}');
insert into t select 'A water before clear', water_oz::text from public.increment_counter('2026-10-15','water_oz',24,'33333333-3333-3333-3333-333333333333');
insert into t select 'A clear', (deleted_at is not null)::text from public.patch_day('2026-10-15','{"clear":true}');
insert into t select 'A replay old op on cleared day (deleted_at|water)', (deleted_at is not null)::text||' | '||water_oz from public.increment_counter('2026-10-15','water_oz',24,'33333333-3333-3333-3333-333333333333');
insert into t select 'A write after clear resets (checks|steps|ex)', checks::text||' | '||coalesce(steps::text,'null')||' | '||exercises::text from public.patch_day('2026-10-15','{"checks":{"clip":true}}');
select set_config('request.jwt.claims','{"sub":"0f0168d7-1afc-4ad6-8d54-6767380b8b7f","role":"authenticated"}',true);
insert into t select 'B sees rows', count(*)::text from public.daily_log;
insert into t select 'B sees ops', count(*)::text from public.counter_ops;
do $$ begin perform public.patch_day('2026-11-01','{"steps":1}'); exception when others then null; end $$;
with u as (update public.daily_log set note='hacked' where user_id='8838982b-cc58-4f06-bc61-6f54aa521b51' returning 1) insert into t select 'B update rows', count(*)::text from u;
do $$ begin insert into public.daily_log(user_id,day) values ('8838982b-cc58-4f06-bc61-6f54aa521b51','2026-10-16'); insert into t values('B insert as A','ALLOWED'); exception when others then insert into t values('B insert as A','denied: '||sqlstate); end $$;
do $$ begin perform public.increment_counter('2026-10-15','water_oz',8,'11111111-1111-1111-1111-111111111111'); insert into t values('B reuse A op_id','no error'); exception when others then insert into t values('B reuse A op_id','denied: '||sqlstate); end $$;
reset role;
set local role anon;
select set_config('request.jwt.claims','{"role":"anon"}',true);
do $$ begin perform 1 from public.daily_log; insert into t values('anon select','ALLOWED'); exception when others then insert into t values('anon select','denied: '||sqlstate); end $$;
do $$ begin perform public.patch_day('2026-10-15','{}'); insert into t values('anon rpc','ALLOWED'); exception when others then insert into t values('anon rpc','denied: '||sqlstate); end $$;
reset role;
insert into t select 'row after B: '||user_id::text||' '||day, note||' steps='||coalesce(steps::text,'null') from public.daily_log where day in ('2026-10-15','2026-11-01');
select * from t;
